use std::alloc::{GlobalAlloc,Layout,System};
use std::sync::atomic::{AtomicUsize,Ordering};
static CALLS:AtomicUsize=AtomicUsize::new(0);static BYTES:AtomicUsize=AtomicUsize::new(0);
struct Counter;
unsafe impl GlobalAlloc for Counter {
 unsafe fn alloc(&self,l:Layout)->*mut u8{CALLS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(l.size(),Ordering::Relaxed);unsafe{System.alloc(l)}}
 unsafe fn alloc_zeroed(&self,l:Layout)->*mut u8{CALLS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(l.size(),Ordering::Relaxed);unsafe{System.alloc_zeroed(l)}}
 unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{CALLS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(n,Ordering::Relaxed);unsafe{System.realloc(p,l,n)}}
 unsafe fn dealloc(&self,p:*mut u8,l:Layout){unsafe{System.dealloc(p,l)}}
}
#[global_allocator]static GLOBAL:Counter=Counter;
fn reset(){CALLS.store(0,Ordering::Relaxed);BYTES.store(0,Ordering::Relaxed);}
fn counts()->(usize,usize){(CALLS.load(Ordering::Relaxed),BYTES.load(Ordering::Relaxed))}
fn main(){
 let mut large=String::new();for i in 0..100{large.push_str(&format!("enum E{i}{{A{i}=0,B{i}=255,C{i}=65536}};enum E{i} f{i}(enum E{i});"));}
 let body=format!("int body(int n){{{}return n;}}", (0..100).map(|i|format!("int local{i}=n+{i};")).collect::<String>());let cases=["typedef int T;struct S{int value;};int f(T);".to_owned(),"enum E{A=0,B=255};struct S{enum E value;};enum E f(enum E);".to_owned(),large,body];
 println!("enum_size {}",std::mem::size_of::<toucan_semantic::Enum>());
 for profile in toucan_target::CompilerProfile::ALL {for (i,source) in cases.iter().enumerate(){for retain in [false,true]{
  let options=toucan_semantic::AnalysisOptions{retain_code:retain,..Default::default()};
  drop(toucan_semantic::analyze_with_profile(source,profile,&options).unwrap());reset();
  let analysis=toucan_semantic::analyze_with_profile(source,profile,&options).unwrap();let semantic=counts();reset();
  let output=toucan_bindings::generate(analysis.unit(),&Default::default()).unwrap();let bindings=counts();
  let dir=std::env::args().nth(1).unwrap();std::fs::write(format!("{dir}/{}-{}-{i}-{retain}.rs",profile.target(),profile.compiler()),&output.source).unwrap();
  println!("{:?} {i} {retain} {} {} {} {}",profile,semantic.0,semantic.1,bindings.0,bindings.1);
 }}}
}

