use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::path::PathBuf;
use std::time::Instant;
use serde::Deserialize;
use serde_json::json;
static CALLS: AtomicUsize = AtomicUsize::new(0);
static BYTES: AtomicUsize = AtomicUsize::new(0);
struct Counter;
unsafe impl GlobalAlloc for Counter {
 unsafe fn alloc(&self, l:Layout)->*mut u8 { CALLS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(l.size(),Ordering::Relaxed);unsafe{System.alloc(l)} }
 unsafe fn alloc_zeroed(&self, l:Layout)->*mut u8 { CALLS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(l.size(),Ordering::Relaxed);unsafe{System.alloc_zeroed(l)} }
 unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8 { CALLS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(n,Ordering::Relaxed);unsafe{System.realloc(p,l,n)} }
 unsafe fn dealloc(&self,p:*mut u8,l:Layout){unsafe{System.dealloc(p,l)}}
}
#[global_allocator] static ALLOCATOR: Counter = Counter;
#[derive(Deserialize)]
struct Request { input:PathBuf, target:String, mode:String, retain:bool, include_dirs:Vec<PathBuf>, definitions:Vec<(String,String)>, allowlist:Vec<String>, max_tokens:usize, nodes:usize, edges:usize, payload:usize, output:Option<PathBuf> }
fn main() {
 let request_path=std::env::args().nth(1).unwrap();
 let request:Request=serde_json::from_slice(&std::fs::read(request_path).unwrap()).unwrap();
 let target: toucan::Target=request.target.parse().unwrap();
 let mut config=toucan::Config::new(target);
 config.analysis.retain_code=request.retain;
 config.analysis.limits=toucan::semantic::checked::Limits{nodes:request.nodes,edges:request.edges,payload_bytes:request.payload};
 config.preprocessor.include_dirs=request.include_dirs;
 config.preprocessor.max_tokens=request.max_tokens;
 for (name,value) in request.definitions {config.preprocessor.defines.insert(name,value);}
 let source=if request.mode=="semantic" {Some(std::fs::read_to_string(&request.input).unwrap())}else{None};
 CALLS.store(0,Ordering::Relaxed);BYTES.store(0,Ordering::Relaxed);
 let started=Instant::now();
 let result=if let Some(source)=source {
  match toucan::semantic::analyze_with_profile(&source,toucan::CompilerProfile::default_for(target),&config.analysis) {
   Ok(analysis)=>{let elapsed=started.elapsed().as_secs_f64();let calls=CALLS.load(Ordering::Relaxed);let bytes=BYTES.load(Ordering::Relaxed);let code=analysis.checked();json!({"status":"accepted","seconds":elapsed,"calls":calls,"bytes":bytes,"declarations":analysis.unit().declarations.len(),"expressions":code.map(|c|c.expressions().len()),"sites":code.map(|c|c.declarations().len())})}
   Err(error)=>json!({"status":"rejected","diagnostic":error.to_string()}),
  }
 }else{
  match toucan::parse_file(&request.input,&config) {
   Ok(compilation)=>{
    let bindings=if request.mode=="bindings" {Some(compilation.bindings(&toucan::BindingOptions{allowlist:request.allowlist,..Default::default()}).unwrap().0)}else{None};
    let elapsed=started.elapsed().as_secs_f64();let calls=CALLS.load(Ordering::Relaxed);let bytes=BYTES.load(Ordering::Relaxed);if let (Some(path),Some(source))=(&request.output,&bindings){std::fs::write(path,source).unwrap();}let code=compilation.checked();json!({"status":"accepted","seconds":elapsed,"calls":calls,"bytes":bytes,"declarations":compilation.unit().declarations.len(),"expressions":code.map(|c|c.expressions().len()),"sites":code.map(|c|c.declarations().len()),"bindings_bytes":bindings.map(|b|b.len())})
   }
   Err(error)=>json!({"status":"rejected","diagnostic":error.to_string()}),
  }
 };
 println!("{}",result);
 if result["status"]!="accepted" {std::process::exit(1);}
}

