from pathlib import Path
import json,subprocess,hashlib,random,statistics,os,datetime
root=Path('/home/dev-user/.cache/toucan/object-alignment-evidence');out=root/'real-resources';inputs=json.loads((out/'inputs.json').read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
binaries={x:Path('/home/dev-user/.cache/toucan/object-alignment-resources-'+x+'-target/release/alignment-resource-probe')for x in ['baseline','current']}
metadata={name:{'path':str(path),'sha256':sha(path),'lock_sha256':sha(root/('driver-'+name)/'Cargo.lock')}for name,path in binaries.items()}
rows=[];rng=random.Random(8092026)
env=os.environ.copy()
for key in ['CPATH','C_INCLUDE_PATH','CFLAGS','CPPFLAGS','SDKROOT','GCC_EXEC_PREFIX','COMPILER_PATH','LIBRARY_PATH']:env.pop(key,None)
env.update(LC_ALL='C',SOURCE_DATE_EPOCH='0')
for sample in range(3):
 cases=inputs.copy();rng.shuffle(cases)
 for case in cases:
  labels=list(binaries);rng.shuffle(labels)
  for label in labels:
   stem=case['id']+'-'+label+'-'+str(sample);rss=out/(stem+'.rss');request=case['request']|{'output':str(out/(stem+'.rs')) if case['request']['mode']=='bindings' else None};req=out/(stem+'.json');req.write_text(json.dumps(request)+'\n')
   cmd=['taskset','-c','4','/usr/bin/time','-f','%M','-o',str(rss),str(binaries[label]),str(req)]
   result=subprocess.run(cmd,capture_output=True,text=True,env=env,timeout=240)
   (out/(stem+'.stdout')).write_text(result.stdout);(out/(stem+'.stderr')).write_text(result.stderr)
   try:measurement=json.loads(result.stdout)
   except Exception:measurement={'status':'no-json','stdout':result.stdout[-2000:],'stderr':result.stderr[-2000:]}
   row={'id':case['id'],'binary':label,'sample':sample,'command':cmd,'exit_code':result.returncode,'peak_rss_kib':int(rss.read_text().strip().splitlines()[-1]),'measurement':measurement}
   if request['output'] and Path(request['output']).is_file():row['bindings_sha256']=sha(Path(request['output']))
   rows.append(row);(out/'runs.json').write_text(json.dumps(rows,indent=2)+'\n');print(case['id'],label,sample,measurement.get('status'),measurement.get('seconds'),flush=True)
   if result.returncode or measurement['status']!='accepted':raise RuntimeError(row)
summary=[]
for case in inputs:
 row={'id':case['id']}
 for label in binaries:
  samples=[r for r in rows if r['id']==case['id'] and r['binary']==label]
  row[label]={key:statistics.median([r['measurement'][key]for r in samples])for key in ['seconds','calls','bytes']}
  row[label]['peak_rss_kib']=statistics.median([r['peak_rss_kib']for r in samples])
  hashes={r.get('bindings_sha256')for r in samples};assert len(hashes)==1
  if None not in hashes:row[label]['bindings_sha256']=next(iter(hashes))
 row['time_ratio']=row['current']['seconds']/row['baseline']['seconds'];row['requested_bytes_delta']=row['current']['bytes']-row['baseline']['bytes'];row['allocation_calls_delta']=row['current']['calls']-row['baseline']['calls']
 if 'bindings_sha256'in row['baseline']:assert row['baseline']['bindings_sha256']==row['current']['bindings_sha256']
 summary.append(row)
assert metadata=={name:{'path':str(path),'sha256':sha(path),'lock_sha256':sha(root/('driver-'+name)/'Cargo.lock')}for name,path in binaries.items()}
report={'measured_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'isolated x86_64 GNU, 4 real header binding generations and 7 compiler-preprocessed real translation units, ordinary and retained, 3 randomized paired samples; allocator instrumentation affects absolute timings','source_sha256':sha(root/'real_resources.rs'),'runner_sha256':sha(Path(__file__)),'binaries':metadata,'inputs':inputs,'summary':summary,'runs':rows}
(out/'report.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps(summary,indent=2))

